-- 0066 Forms round (OPI feedback 2026-10-13):
--  * Daily Update: JHA section removed (now its own Safety form), Equipment gets
--    an optional photo/video upload, saw-cut text fixed (the 0052 seed lost the
--    backslashes of its unicode escapes), Epoxy Machine section moved here from
--    the WG Trailer form (shown when Wire Guidance is on for the project).
--  * New form daily_jha (Safety Forms group in the PM Forms tab). Projects that
--    had the old JHA section switched on get the new form required.
--  * Completion: ERG text fixed, customer sign-off becomes a signature pad with
--    a "No signature" option.
UPDATE form_templates SET definition = '{"sections": [{"key": "progress_video", "title": "Progress Video", "toggle": "always", "questions": [{"key": "progress_video", "hint": "30 to 60 seconds", "type": "video", "label": "Upload a 30 - 60 Second video showcasing the progress of the day.", "allow_none": "No video today"}]}, {"key": "marked_drawings", "title": "Marked Drawings", "toggle": "always", "questions": [{"key": "marked_drawings", "hint": "Yellow = in progress, Green = completed, Red = Redflag/CO", "type": "media", "label": "Marked the PDF drawings to show what we are working on and what is completed.", "multiple": true}]}, {"key": "equipment", "title": "Equipment", "toggle": "always", "questions": [{"key": "equipment_down", "type": "yes_no", "label": "Is any of the equipment down?", "branches": {"no": [], "yes": [{"key": "equipment_down_desc", "type": "text", "label": "Provide a brief description of problem"}, {"key": "equipment_down_photos", "type": "photos", "label": "Photos of asset #", "multiple": true}]}, "red_flag_on": "yes"}, {"key": "equipment_media", "type": "media", "multiple": true, "optional": true, "label": "Upload photos/videos of the equipment (if applicable)"}]}, {"key": "propane", "title": "Propane/Fuel", "toggle": "always", "questions": [{"key": "propane_low", "type": "yes_no", "label": "Are we low on Propane/Fuel?", "branches": {"no": [], "yes": [{"key": "propane_tanks_left", "type": "number", "label": "How many tanks are left?"}]}}]}, {"key": "layout_changes", "title": "Layout / Elevation Changes", "toggle": "always", "questions": [{"key": "layout_changes", "type": "yes_no", "label": "Were any changes made to the layout or elevation today with the approval of OPI PM?", "branches": {"no": [], "yes": [{"key": "layout_changes_desc", "type": "text", "label": "Provide a brief description of changes made"}, {"key": "layout_changes_photos", "type": "photos", "label": "Photos of changes made", "multiple": true}]}, "red_flag_on": "yes"}]}, {"key": "shortages", "title": "Material Shortages / Damages", "toggle": "always", "questions": [{"key": "material_shortages", "type": "yes_no", "label": "Are there any material shortages or damages to report?", "branches": {"no": [], "yes": [{"key": "shortage_item_desc", "type": "text", "label": "Provide item description"}, {"key": "shortage_photos", "type": "photos", "label": "Photos", "multiple": true}, {"key": "shortage_counts", "type": "text", "label": "Counts"}]}, "red_flag_on": "yes"}]}, {"key": "anchoring", "title": "Anchoring", "toggle": "anchoring", "questions": [{"key": "anchoring_video", "type": "video", "label": "Upload Video showcasing proper anchoring procedures."}]}, {"key": "wire_guidance", "title": "Wire Guidance", "toggle": "wire_guidance", "questions": [{"key": "wg_saw_cut", "type": "media", "count": 3, "label": "Upload 3 Photos/Videos of 1/2\\" depth saw cut in different areas throughout the system.", "multiple": true}, {"key": "wg_expansion_joints", "type": "video", "label": "Upload a Video showing the expansion joints foam and silicon installed."}, {"key": "wg_continuity", "type": "video", "label": "Upload a Video showing continuity in wire at line driver box prior to epoxy pour."}, {"key": "wg_aisles_clean", "type": "media", "label": "Upload Photos/Videos showing the aisles cleaned and completed.", "multiple": true}, {"key": "wg_ohms_final", "type": "video", "label": "Upload a Final video of ohms reading at line driver box with it written inside the box."}]}, {"key": "epoxy_machine", "title": "Epoxy Machine", "toggle": "wire_guidance", "questions": [{"key": "wgt_xylene_video", "hint": "30 seconds", "type": "video", "label": "Upload 30 Sec Video of Xylane Cycling through Epoxy machine"}, {"key": "wgt_oil_photo", "type": "photos", "label": "Upload a Photo of Epoxy machine with Oil in tanks"}]}]}' WHERE code = 'daily_update';

UPDATE form_templates SET definition = '{"sections": [{"key": "completed_photos", "title": "Completed Project Photos", "toggle": "always", "questions": [{"key": "completed_photos", "hint": "Provide photos showing aisle widths, elevation levels, footplates w/ anchors, bolts torqued for knockdown uprights and any detail work. (palletback stops showcasing tek screws, ERG showcasing anchors, netting etc.)", "type": "photos", "count": 10, "label": "Upload 10 Photos showcasing the completed project", "multiple": true}]}, {"key": "completed_video", "title": "Completed Project Video", "toggle": "always", "questions": [{"key": "completed_video", "hint": "30 to 60 seconds", "type": "video", "label": "Upload a 30 to 60 second video showcasing the completed project."}]}, {"key": "resubmissions", "title": "Resubmit anchoring video & final wire guidance ohms reading (If applicable)", "toggle": "always", "questions": [{"key": "resubmit_anchoring_video", "type": "video", "label": "Resubmit anchoring video (If applicable)", "optional": true}, {"key": "resubmit_wg_ohms_video", "type": "video", "label": "Resubmit final wire guidance ohms reading (If applicable)", "optional": true}]}, {"key": "additional_comments", "title": "Additional Information", "toggle": "always", "questions": [{"key": "additional_comments", "type": "yes_no", "label": "Is there any additional information or comments to report from the crew lead or client?", "branches": {"no": [], "yes": [{"key": "additional_comments_text", "type": "text", "label": "Comments from the crew lead or client"}, {"key": "additional_comments_media", "type": "media", "label": "Media upload", "multiple": true}]}}]}, {"key": "customer_signoff", "title": "Customer Sign off", "toggle": "always", "questions": [{"key": "customer_signoff", "type": "signature", "label": "Customer signature", "hint": "Have the customer sign below with a finger or stylus.", "allow_none": "No signature - customer not on site"}]}]}' WHERE code = 'completion';

UPDATE form_templates
SET definition = JSON_REMOVE(definition, '$.sections[0]')
WHERE code = 'wire_guidance_trailer'
  AND JSON_UNQUOTE(JSON_EXTRACT(definition, '$.sections[0].key')) = 'epoxy_machine';

INSERT INTO form_templates (code, title, definition, sort_order, active)
SELECT 'daily_jha', 'Daily OPI JHA (Job Hazard Analysis)', '{"category": "safety", "sections": [{"key": "jha", "title": "Daily OPI JHA", "toggle": "always", "questions": [{"key": "jha_hazards", "type": "text", "label": "Job Hazard Analysis: what hazards did you notice on the jobsite today?"}, {"key": "jha_prevention", "type": "text", "label": "What prevention steps were taken for those hazards?"}]}]}', 80, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM form_templates WHERE code = 'daily_jha');

UPDATE project_form_settings
SET forms = JSON_SET(COALESCE(forms, JSON_OBJECT()), '$.daily_jha', JSON_OBJECT('required', TRUE))
WHERE JSON_EXTRACT(toggles, '$.jha') = TRUE;
